18	package org.apache.hadoop.hdfs;
19	
20	import org.apache.hadoop.thirdparty.com.google.common.base.Preconditions;
21	import org.apache.hadoop.fs.ChecksumException;
22	import org.apache.hadoop.hdfs.protocol.DatanodeInfo;
23	import org.apache.hadoop.hdfs.protocol.ErasureCodingPolicy;
24	import org.apache.hadoop.hdfs.protocol.ExtendedBlock;
