92	
93	  /**
94	   * Check and ensure the buffers are of the desired length and type, direct
95	   * buffers or not.
96	   * @param buffers the buffers to check
97	   */
98	  void checkInputBuffers(ByteBuffer[] buffers) {
99	    int validInputs = 0;
100	
101	    for (ByteBuffer buffer : buffers) {
102	      if (buffer == null) {
103	        continue;
104	      }
105	
106	      if (buffer.remaining() != decodeLength) {
107	        throw new HadoopIllegalArgumentException(
108	            "Invalid buffer, not of length " + decodeLength);
109	      }
110	      if (buffer.isDirect() != usingDirectBuffer) {
111	        throw new HadoopIllegalArgumentException(
112	            "Invalid buffer, isDirect should be " + usingDirectBuffer);
113	      }
114	
115	      validInputs++;
