233	  boolean createBlockReader(LocatedBlock block, long offsetInBlock,
234	      LocatedBlock[] targetBlocks, BlockReaderInfo[] readerInfos,
235	      int chunkIndex) throws IOException {
236	    BlockReader reader = null;
237	    final ReaderRetryPolicy retry = new ReaderRetryPolicy();
238	    DFSInputStream.DNAddrPair dnInfo =
239	        new DFSInputStream.DNAddrPair(null, null, null, null);
240	
241	    while (true) {
242	      try {
243	        // the cached block location might have been re-fetched, so always
244	        // get it from cache.
245	        block = refreshLocatedBlock(block);
246	        targetBlocks[chunkIndex] = block;
247	
248	        // internal block has one location, just rule out the deadNodes
249	        dnInfo = getBestNodeDNAddrPair(block, null);
250	        if (dnInfo == null) {
251	          break;
252	        }
253	        reader = getBlockReader(block, offsetInBlock,
254	            block.getBlockSize() - offsetInBlock,
255	            dnInfo.addr, dnInfo.storageType, dnInfo.info);
256	      } catch (IOException e) {
257	        if (e instanceof InvalidEncryptionKeyException &&
258	            retry.shouldRefetchEncryptionKey()) {
259	          DFSClient.LOG.info("Will fetch a new encryption key and retry, "
260	              + "encryption key was invalid when connecting to " + dnInfo.addr
261	              + " : " + e);
262	          dfsClient.clearDataEncryptionKey();
263	          retry.refetchEncryptionKey();
264	        } else if (retry.shouldRefetchToken() &&
265	            tokenRefetchNeeded(e, dnInfo.addr)) {
266	          fetchBlockAt(block.getStartOffset());
267	          retry.refetchToken();
268	        } else {
269	          //TODO: handles connection issues
270	          DFSClient.LOG.warn("Failed to connect to " + dnInfo.addr + " for " +
271	              "block" + block.getBlock(), e);
272	          // re-fetch the block in case the block has been moved
273	          fetchBlockAt(block.getStartOffset());
274	          addToLocalDeadNodes(dnInfo.info);
275	        }
276	      }
277	      if (reader != null) {
278	        readerInfos[chunkIndex] =
279	            new BlockReaderInfo(reader, dnInfo.info, offsetInBlock);
280	        return true;
281	      }
282	    }
283	    return false;
