286	  /**
287	   * Read a new stripe covering the current position, and store the data in the
288	   * {@link #curStripeBuf}.
289	   */
290	  private void readOneStripe(CorruptedBlocks corruptedBlocks)
291	      throws IOException {
292	    resetCurStripeBuffer(true);
293	
294	    // compute stripe range based on pos
295	    final long offsetInBlockGroup = getOffsetInBlockGroup();
296	    final long stripeLen = cellSize * dataBlkNum;
297	    final int stripeIndex = (int) (offsetInBlockGroup / stripeLen);
298	    final int stripeBufOffset = (int) (offsetInBlockGroup % stripeLen);
299	    final int stripeLimit = (int) Math.min(currentLocatedBlock.getBlockSize()
300	        - (stripeIndex * stripeLen), stripeLen);
301	    StripeRange stripeRange =
302	        new StripeRange(offsetInBlockGroup, stripeLimit - stripeBufOffset);
303	
304	    LocatedStripedBlock blockGroup = (LocatedStripedBlock) currentLocatedBlock;
305	    AlignedStripe[] stripes = StripedBlockUtil.divideOneStripe(ecPolicy,
306	        cellSize, blockGroup, offsetInBlockGroup,
307	        offsetInBlockGroup + stripeRange.getLength() - 1, curStripeBuf);
308	    final LocatedBlock[] blks = StripedBlockUtil.parseStripedBlockGroup(
309	        blockGroup, cellSize, dataBlkNum, parityBlkNum);
310	    // read the whole stripe
311	    for (AlignedStripe stripe : stripes) {
312	      // Parse group to get chosen DN location
313	      StripeReader sreader = new StatefulStripeReader(stripe, ecPolicy, blks,
314	          blockReaders, corruptedBlocks, decoder, this);
315	      sreader.readStripe();
316	    }
317	    curStripeBuf.position(stripeBufOffset);
318	    curStripeBuf.limit(stripeLimit);
319	    curStripeRange = stripeRange;
320	  }
