391	    if (pos < getFileLength()) {
392	      try {
393	        if (pos > blockEnd) {
394	          blockSeekTo(pos);
395	        }
396	        int realLen = (int) Math.min(len, (blockEnd - pos + 1L));
397	        synchronized (infoLock) {
398	          if (locatedBlocks.isLastBlockComplete()) {
399	            realLen = (int) Math.min(realLen,
400	                locatedBlocks.getFileLength() - pos);
401	          }
402	        }
