58	    Preconditions.checkState(index >= dataBlkNum &&
59	        alignedStripe.chunks[index] == null);
60	
61	    int bufLen = (int) alignedStripe.getSpanInBlock();
62	    decodeInputs[index] = new ECChunk(codingBuffer.duplicate(), index * bufLen,
63	        bufLen);
64	
65	    alignedStripe.chunks[index] =
66	        new StripingChunk(decodeInputs[index].getBuffer());
