78	    int bufLen = (int) alignedStripe.getSpanInBlock();
79	    int bufCount = dataBlkNum + parityBlkNum;
80	    codingBuffer = dfsStripedInputStream.getBufferPool().
81	        getBuffer(useDirectBuffer(), bufLen * bufCount);
82	    ByteBuffer buffer;
83	    for (int i = 0; i < dataBlkNum; i++) {
84	      buffer = codingBuffer.duplicate();
85	      decodeInputs[i] = new ECChunk(buffer, i * bufLen, bufLen);
86	    }
87	
88	    for (int i = 0; i < dataBlkNum; i++) {
89	      if (alignedStripe.chunks[i] == null) {
90	        alignedStripe.chunks[i] =
91	            new StripingChunk(decodeInputs[i].getBuffer());
